## Code Example
```c
// Minimal sketch of fast-path vs slow-path for futex_wait
typedef struct { atomic_int *addr; wait_queue_t *wq; robust_list_t *robust; } futex_t;
int futex_wait(int *addr, int expected) {
  // Fast path: if *addr != expected, return immediately
  if (atomic_load(addr) != expected) return EAGAIN;

  // Slow path: enqueue and block
  futex_t f = {addr, get_wait_queue(addr), current->robust_list};
  add_to_robust_list(&f);
  smp_mb(); // Memory barrier before sleep
  return wait_event_interruptible(f.wq, atomic_load(addr) != expected);
}
```

